// 1. Configuração da Equipe
const equipe = [
    { alias: "Lucas",     match: ["Lucas", "Luc"] },
    { alias: "Porto",     match: ["Porto", "Felipe"] },
    { alias: "Guilherme", match: ["Guilherme", "Gui"] },
    { alias: "Igor",      match: ["Igor", "Vilas Boas"] },
    { alias: "Léo",       match: ["Leonardo", "Leo", "Léo"] }
];

// Função segura para pegar dados do item
function getDados(item) {
    return (item && item.json) ? item.json : item;
}

// Função para extrair nomes de responsáveis
function extrairNomes(assignees) {
    if (!assignees) return "";
    if (typeof assignees === 'string') return assignees;
    if (Array.isArray(assignees)) {
        return assignees.map(u => {
            if (typeof u === 'object' && u !== null && u.username) return u.username;
            return String(u);
        }).join(", ");
    }
    return String(assignees);
}

// Função para gerar a Tag de Status
function getStatusTag(statusRaw) {
    const status = (typeof statusRaw === 'string' ? statusRaw : statusRaw?.status || "").toLowerCase();

    if (['complete', 'closed', 'done', 'concluído', 'finalizado', 'fechado'].includes(status)) {
        return "**🟢[CONCLUÍDO]**";
    }
    if (['in progress', 'fazendo', 'em progresso', 'andamento', 'executando'].includes(status)) {
        return "**🟣[EM PROGRESSO]**";
    }
    return "**⚪[PENDENTE]**";
}

// 2. Recebe e Classifica os dados do nó "Uni informações"
let todosItens = [];
try {
    todosItens = $items("Uni informações");
} catch (error) {
    todosItens = $input.all(); 
}

const concluidas = todosItens.filter(item => {
    const d = getDados(item);
    const statusLower = (typeof d.status === 'string' ? d.status : d.status?.status || "").toLowerCase();
    return (statusLower === 'complete' || statusLower === 'closed' || d.date_closed);
});

const atrasadas = todosItens.filter(item => {
    const d = getDados(item);
    return d.motivo === "Prazo Expirado";
});

const hoje = todosItens.filter(item => {
    const d = getDados(item);
    const statusLower = (typeof d.status === 'string' ? d.status : d.status?.status || "").toLowerCase();
    return (d.motivo && d.motivo !== "Prazo Expirado" && statusLower !== 'complete' && statusLower !== 'closed');
});

// 3. Função Geradora de Texto
// Novo parâmetro opcional: 'msgIndividualSeVazio'
function gerarSecao(titulo, listaDeTarefas, mensagemSeVazio, msgIndividualSeVazio = null) {
    let texto = `\n### ${titulo}\n`;
    let encontrouAlguma = false;
    let bufferMembros = "";

    equipe.forEach(membro => {
        const tarefasDaPessoa = listaDeTarefas.filter(item => {
            const dados = getDados(item);
            const responsaveis = extrairNomes(dados.assignees).toLowerCase();
            return membro.match.some(termo => responsaveis.includes(termo.toLowerCase()));
        });

        // CASO 1: Tem tarefas
        if (tarefasDaPessoa.length > 0) {
            encontrouAlguma = true;
            bufferMembros += `\n**${membro.alias}:**\n`; 

            tarefasDaPessoa.forEach((t) => {
                const dados = getDados(t);

                let taskUrl = dados.url;
                if (!taskUrl && dados.id) {
                    taskUrl = `https://app.clickup.com/t/${dados.id}`;
                }
                const nomeTarefa = dados.name || "Tarefa sem nome";
                const statusPrefix = getStatusTag(dados.status);

                let linhaTarefa = "";
                if (taskUrl) {
                    linhaTarefa = `- ${statusPrefix} - ${nomeTarefa} ([Link](${taskUrl}))`; 
                } else {
                    linhaTarefa = `- ${statusPrefix} - ${nomeTarefa}`;
                }
                bufferMembros += `${linhaTarefa}\n`;
            });
        } 
        // CASO 2: Não tem tarefas, mas a seção exige mostrar todos (ex: "Hoje")
        else if (msgIndividualSeVazio) {
            encontrouAlguma = true; // Consideramos que houve conteúdo para não mostrar a msg global
            bufferMembros += `\n**${membro.alias}:**\n`;
            bufferMembros += `- ${msgIndividualSeVazio}\n`;
        }
        // CASO 3: Não tem tarefas e não exige mostrar todos (ex: "Concluídas") -> Não faz nada
    });

    if (!encontrouAlguma) {
        texto += `_${mensagemSeVazio || "Nenhuma tarefa encontrada."}_\n`;
    } else {
        texto += bufferMembros;
    }

    return texto;
}

// 4. Montagem Final
const dataHoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });


const relatorioFinal = `
${gerarSecao("Tarefas Concluídas no dia anterior", concluidas, "Não tivemos nenhuma tarefa concluída ontem")}
${gerarSecao("Tarefas de hoje", hoje, "Nenhuma tarefa para hoje.", "Está sem demanda")}
${gerarSecao("Tarefas atrasadas", atrasadas, "Não temos tarefas atrasadas!")}
`;

return {
    json: {
        data: dataHoje,
        documentoTexto: relatorioFinal
    }
};

// 1. Configurações e Data
const ID_PASTA_MAE = "8cj86vj-77071"; // <--- O ID ONDE VAMOS PROCURAR O MÊS

function getMesAnoAtual() {
    const data = new Date();
    const mes = data.toLocaleString('pt-BR', { month: 'long', timeZone: 'America/Sao_Paulo' });
    const ano = data.getFullYear();

    // Garante primeira letra maiúscula e adiciona o ano (ex: "Dezembro - 2025")
    const mesFormatado = mes.charAt(0).toUpperCase() + mes.slice(1);
    return `${mesFormatado} - ${ano}`;
}

const nomeAlvo = getMesAnoAtual(); // Ex: "Dezembro - 2025"

// 2. Recebe os dados
const inputData = $input.first().json;
const paginasIniciais = Array.isArray(inputData) ? inputData : (inputData.pages || []);

// 3. Função Recursiva para encontrar a PASTA MÃE pelo ID
function encontrarPastaPorId(listaPaginas, idBuscado) {
    if (!listaPaginas || listaPaginas.length === 0) return null;

    for (const pagina of listaPaginas) {
        // Verifica se é a pasta mãe que queremos
        if (pagina.id === idBuscado) {
            return pagina;
        }

        // Se não for, procura nas filhas
        if (pagina.pages && pagina.pages.length > 0) {
            const encontrada = encontrarPastaPorId(pagina.pages, idBuscado);
            if (encontrada) return encontrada;
        }
    }
    return null;
}

// 4. Execução da Lógica
// PASSO A: Encontra a pasta mãe (77071) onde tudo deve ser salvo
const pastaMae = encontrarPastaPorId(paginasIniciais, ID_PASTA_MAE);

if (!pastaMae) {
    return {
        json: {
            encontrado: false,
            mensagem: `❌ Erro Crítico: A pasta mãe fixa (ID: ${ID_PASTA_MAE}) não foi encontrada no ClickUp.`,
            nomeBuscado: nomeAlvo
        }
    };
}

// PASSO B: Procura o Mês (ex: Dezembro - 2025) APENAS dentro das filhas diretas da pasta mãe
// Isso evita pegar um "Dezembro" de outro ano perdido em outra pasta
let paginaDoMes = null;

if (pastaMae.pages && pastaMae.pages.length > 0) {
    paginaDoMes = pastaMae.pages.find(p => p.name.trim().toLowerCase() === nomeAlvo.toLowerCase());
}

// 5. Resultado Final
if (!paginaDoMes) {
    return {
        json: {
            encontrado: false,
            // Importante: Passamos o ID da mãe para o próximo nó saber onde criar o mês
            parentPageId: pastaMae.id, 
            docId: pastaMae.doc_id,
            mensagem: `⚠️ Pasta "${nomeAlvo}" não existe dentro de (ID: ${ID_PASTA_MAE}). Precisa ser criada.`,
            nomeBuscado: nomeAlvo
        }
    };
}

// Sucesso!
return {
    json: {
        encontrado: true,
        parentPageId: paginaDoMes.id, // O ID do Mês (onde vamos salvar a semana)
        docId: paginaDoMes.doc_id,
        nomePagina: paginaDoMes.name,
        mensagem: `Sucesso! Encontrada "${paginaDoMes.name}" dentro da pasta mãe.`
    }
};

// 1. Configuração da Equipe
const equipe = [
    { alias: "Lucas",     match: ["Lucas", "Luc"] },
    { alias: "Porto",     match: ["Porto", "Felipe"] },
    { alias: "Guilherme", match: ["Guilherme", "Gui"] },
    { alias: "Igor",      match: ["Igor", "Vilas Boas"] },
    { alias: "Léo",       match: ["Leonardo", "Leo", "Léo"] }
];

// 2. Pega os dados que vieram do nó "Uni informações"
// Usamos $input.all() para pegar tudo que entrou neste nó
let tarefas = [];
try {
    tarefas = $input.all().map(item => item.json);
} catch (error) {
    tarefas = [];
}

// 3. Inicializa contadores
const metricas = {};
equipe.forEach(m => {
    metricas[m.alias] = { 
        concluidas: 0, 
        em_progresso: 0, 
        atrasadas: 0,
        pausadas: 0 // Novo contador para Pausadas
    };
});

// Função auxiliar para identificar dono
function identificarDono(assignees) {
    if (!assignees) return null;
    const responsaveis = (typeof assignees === 'string' ? assignees : JSON.stringify(assignees)).toLowerCase();
    return equipe.find(membro => membro.match.some(termo => responsaveis.includes(termo.toLowerCase())));
}

// 4. Processa as tarefas
tarefas.forEach(task => {
    const dono = identificarDono(task.assignees);

    if (dono) {
        const statusLower = String(task.status || "").toLowerCase();

        // A: Concluída (baseado no status ou data de fechamento)
        if (['complete', 'closed', 'done', 'concluído', 'finalizado', 'fechado'].includes(statusLower) || task.date_closed) {
            metricas[dono.alias].concluidas++;
        }
        // B: Atrasada (baseado no motivo que seus filtros criaram)
        else if (task.motivo === "Prazo Expirado") {
            metricas[dono.alias].atrasadas++;
        }
        // C: Pausada (Nova lógica)
        else if (['pause', 'paused', 'pausa', 'pausado', 'on hold', 'espera'].includes(statusLower)) {
            metricas[dono.alias].pausadas++;
        }
        // D: Em Progresso (todo o resto)
        else {
            metricas[dono.alias].em_progresso++;
        }
    }
});

// 5. Prepara para o Supabase
// Gera data de hoje (YYYY-MM-DD)
const dataHoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }).split('/').reverse().join('-');

const linhasSupabase = Object.keys(metricas).map(nome => {
    return {
        json: {
            data_registro: dataHoje,
            membro: nome,
            concluidas: metricas[nome].concluidas,
            em_progresso: metricas[nome].em_progresso,
            atrasadas: metricas[nome].atrasadas,
            pausadas: metricas[nome].pausadas // Nova coluna para o Supabase
        }
    };
});

return linhasSupabase;

// Define datas para filtros
const agora = new Date();
const ontem = new Date(agora);
ontem.setDate(ontem.getDate() - 1);

// Timestamp em milissegundos (Formato ClickUp)
const inicioHoje = new Date(agora.setHours(0,0,0,0)).getTime();
const inicioOntem = new Date(ontem.setHours(0,0,0,0)).getTime();
const fimOntem = new Date(ontem.setHours(23,59,59,999)).getTime();

return {
  json: {
    inicioHoje,
    inicioOntem,
    fimOntem,
    dataFormatada: agora.toLocaleDateString('pt-BR')
  }
};

// Recebe as tarefas do nó anterior
const tarefas = $items("Tarefas Em Progresso/Hoje");

// --- CONFIGURAÇÃO DE DATA (FUSO BRASIL) ---
const now = new Date();

// 1. String visual para comparação exata (ex: "02/12/2025")
const hojeString = now.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// 2. Objeto Date (Meia-noite) para cálculo matemático de atraso
const inicioHoje = new Date(now.toLocaleDateString('en-US', { timeZone: 'America/Sao_Paulo' }));

// Helper: Converte timestamp ms para String "DD/MM/AAAA"
function dataParaStringBR(timestamp) {
    if (!timestamp) return null;
    return new Date(parseInt(timestamp)).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
}

const tarefasFiltradas = [];

for (const item of tarefas) {
  const task = item.json;

  // Tratamento do Status
  const statusObj = task.status;
  const statusText = (statusObj && statusObj.status) ? statusObj.status : (statusObj || "");
  const statusLower = statusText.toString().toLowerCase();

  // Datas
  const startDateStr = dataParaStringBR(task.start_date);
  const dueDateStr = dataParaStringBR(task.due_date);

  const startTimestamp = task.start_date ? parseInt(task.start_date) : null;
  const dueTimestamp = task.due_date ? parseInt(task.due_date) : null;
  const nowTimestamp = now.getTime();

  // Responsáveis
  const responsaveis = (task.assignees && task.assignees.length > 0)
    ? task.assignees.map(user => user.username).join(", ")
    : "Sem responsável";

  let deveIncluir = false;
  let motivo = "";

  // Verifica se está atrasada (Vencimento menor que o início de hoje)
  // Usado para filtrar Paused tasks que já deveriam estar no relatório de atrasos
  const estaAtrasada = (dueTimestamp && dueTimestamp < inicioHoje.getTime());

  // --- REGRA 1: Em Progresso (Sempre inclui) ---
  if (['in progress', 'fazendo', 'em progresso', 'andamento'].some(s => statusLower.includes(s))) {
    deveIncluir = true;
    motivo = "Em Andamento";
  }

  // --- REGRA 2: Pausado (Inclui APENAS se estiver "No Prazo") ---
  // Se estiver atrasada, ignoramos aqui (pois já caiu no script de Atrasadas)
  else if (['pause', 'pausado', 'espera', 'hold'].some(s => statusLower.includes(s))) {
      if (!estaAtrasada) {
          deveIncluir = true;
          motivo = "Pausado (No Prazo)";
      }
  }

  // --- REGRA 3: Tarefas "A Fazer" (To Do) ---
  else {
      // A: Vence HOJE?
      if (dueDateStr === hojeString) {
        deveIncluir = true;
        motivo = "Vence Hoje!";
      }

      // B: Começa HOJE?
      else if (startDateStr === hojeString) {
        deveIncluir = true;
        motivo = "Início Hoje";
      }

      // C: Já deveria ter começado? (Passado do Start Date e ainda parado)
      else if (startTimestamp && startTimestamp < nowTimestamp) {
         deveIncluir = true;
         motivo = "Deveria ter iniciado";
      }
  }

  if (deveIncluir) {
    tarefasFiltradas.push({
      json: {
        name: task.name,
        status: statusText,
        url: task.url,
        assignees: responsaveis,
        start_date: startDateStr,
        due_date: dueDateStr,
        motivo: motivo
      }
    });
  }
}

return tarefasFiltradas;

// Recebe as tarefas do nó anterior
const tarefas = $items("Tarefas Concluídas Ontem"); 

// --- CONFIGURAÇÃO DE FUSO E DATA ---
const offsetBrasil = -3; // Fuso horário UTC-3

// 1. Definir o "AGORA"
// EM PRODUÇÃO: Use a linha abaixo
let hoje = new Date();

// PARA TESTES (Descomente para simular data atual diferente)
// hoje = new Date("2025-12-02T10:00:00"); 

// 2. Calcular o intervalo exato de "ONTEM" (00:00:00 até 23:59:59)
const nowUTC = hoje.getTime();
const nowBrasil = new Date(nowUTC + (offsetBrasil * 3600 * 1000));

const ano = nowBrasil.getUTCFullYear();
const mes = nowBrasil.getUTCMonth();
const dia = nowBrasil.getUTCDate();

// Cria timestamps absolutos para o início e fim de ONTEM
const inicioOntemMs = Date.UTC(ano, mes, dia - 1, 0, 0, 0) - (offsetBrasil * 3600 * 1000);
const fimOntemMs = Date.UTC(ano, mes, dia - 1, 23, 59, 59, 999) - (offsetBrasil * 3600 * 1000);

// FORMATADORES DE DATA (Apenas para visualização no debug)
const opcoesBr = { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' };
const inicioLegivel = new Date(inicioOntemMs).toLocaleString('pt-BR', opcoesBr);
const fimLegivel = new Date(fimOntemMs).toLocaleString('pt-BR', opcoesBr);

const tarefasFiltradas = [];

for (const item of tarefas) {
  const task = item.json;

  // --- ALTERAÇÃO PRINCIPAL ---
  // Antes: const dataFechamentoRaw = task.date_closed || task.date_done;
  // Agora: Pega estritamente o date_done. Se for nulo, ignora a tarefa.
  const dataConclusaoRaw = task.date_done;

  if (!dataConclusaoRaw) continue; 

  const dataConclusaoMs = parseInt(dataConclusaoRaw);

  // --- FILTRO MATEMÁTICO ---
  // Verifica se a DATA DE CONCLUSÃO (trabalho feito) foi ontem
  if (dataConclusaoMs >= inicioOntemMs && dataConclusaoMs <= fimOntemMs) {

    // Formata data da tarefa
    const dataVisual = new Date(dataConclusaoMs).toLocaleString('pt-BR', opcoesBr);

    const responsaveis = (task.assignees && task.assignees.length > 0)
      ? task.assignees.map(user => user.username).join(", ")
      : "Sem responsável";

    tarefasFiltradas.push({
      json: {
        name: task.name,
        status: task.status.status,
        url: task.url, // Certifique-se que o campo url vem do nó anterior ou monte ele aqui
        assignees: responsaveis,
        date_done_formatted: dataVisual, // Mudei o nome para ficar claro que é data de conclusão

        // --- DEBUG ---
        debug_intervalo_filtro: `De ${inicioLegivel} até ${fimLegivel}`,
        debug_data_usada: dataVisual
      }
    });
  }
}

return tarefasFiltradas;

// Recebe as tarefas do nó anterior
const tarefas = $items("Tarefas Atrasadas"); 

// --- CONFIGURAÇÃO DE DATAS (FUSO BRASIL) ---
// 1. Pega o momento atual
const now = new Date();

// 2. Cria um objeto Date representando o início de HOJE em SP (00:00:00)
const hojeString = now.toLocaleDateString('en-US', { timeZone: 'America/Sao_Paulo' });
const inicioHoje = new Date(hojeString); // Data de hoje à meia-noite

const tarefasFiltradas = [];

// Lista de status que IGNORAMOS (não contam como atraso)
// NOTA: Como 'pause', 'paused' e 'em espera' NÃO estão aqui, eles serão verificados.
const statusFinalizados = [
    'complete', 
    'closed', 
    'done', 
    'concluído', 
    'fechado', 
    'canceled', 
    'cancelado'
];

for (const item of tarefas) {
  const task = item.json;

  // Normaliza o status para minúsculo para evitar erros de digitação
  const statusObj = task.status;
  const statusText = (statusObj && statusObj.status) ? statusObj.status : (statusObj || "");
  const statusLower = statusText.toString().toLowerCase();

  // 1. FILTRO DE STATUS
  // Se estiver na lista de finalizados/cancelados, ignora.
  // Se for "PAUSE", ele passa por aqui e vai checar a data abaixo.
  if (statusFinalizados.includes(statusLower)) {
      continue;
  }

  // Data de vencimento (em milissegundos)
  const dueDateMs = task.due_date ? parseInt(task.due_date) : null;

  let estaAtrasada = false;
  let dataVencimentoStr = "Sem data";

  if (dueDateMs) {
      // Cria data do vencimento no fuso correto
      const vencimentoString = new Date(dueDateMs).toLocaleDateString('en-US', { timeZone: 'America/Sao_Paulo' });
      const dataVencimento = new Date(vencimentoString); // Vencimento à meia-noite

      // Formata para leitura humana (PT-BR)
      dataVencimentoStr = new Date(dueDateMs).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

      // 2. FILTRO DE DATA
      // REGRA: Vencimento é estritamente MENOR que Hoje?
      // Ex: Vencimento (Ontem) < Hoje (Agora) = TRUE (Atrasada)
      if (dataVencimento < inicioHoje) {
          estaAtrasada = true;
      }
  }

  // --- Extrair Responsáveis ---
  const responsaveis = (task.assignees && task.assignees.length > 0)
    ? task.assignees.map(user => user.username).join(", ")
    : "Sem responsável";

  if (estaAtrasada) {
    tarefasFiltradas.push({
      json: {
        name: task.name,
        status: statusText, // Mantém o nome original (ex: "paused")
        url: task.url,
        assignees: responsaveis,
        due_date: dataVencimentoStr,
        motivo: "Prazo Expirado"
      }
    });
  }
}

return tarefasFiltradas;
